  str_n28_1_name_desc = "/",
  str_n28_2_name_desc = "Sebuah kasus tentang patung yang dipenggal ditempatkan dalam tanggung jawab Anda, namun, klaim penggugat bukanlah kerusakan pada properti umum, tetapi... penghalang cinta?",
  str_n28_3_name_desc = "Di musim ini, ketika semangat Hari Mahkota Bulan masih mengudara, Tina memiliki keinginannya sendiri untuk dikejar.",
  str_n28_4_name_desc = "Pergi dan alami Moonlight Salon yang legendaris, benamkan diri Anda dalam suasana asmara, dan temukan kebenaran!",
  str_n28_5_name_desc = "/",
  str_n28_6_name_desc = "Hanya ketika rasa malu Schwab menjadi jelas, Anda menyadari kesalahpahaman mengerikan yang telah terjadi.",
  str_n28_7_name_desc = "Anda menemukan pengelola salon, seorang biarawati biasa dari Lumopolis, tetapi menerima beberapa jawaban yang tidak terduga.",
  str_n28_8_name_desc = "/",
  str_n28_9_name_desc = "Gerhana, di saat seperti ini? Mereka benar-benar makhluk aneh...",
  str_n28_10_name_desc = "Saat ancaman Eclipsite secara bertahap mendekati patung, jangan lupa untuk melindungi patung tersebut dalam pertempuran!",
  str_n28_11_name_desc = "Singkirkan pengejar di belakang Anda dan bersiaplah untuk bertarung tanpa batasan apa pun!",
  str_n28_12_name_desc = "Apakah ruang bawah tanah semua bangsawan dipenuhi dengan begitu banyak kotoran!?",
  str_n28_13_name_desc = "Jangan biarkan detail terkecil meluncur tanpa pengawasan—ungkapkan kebenaran di balik kasus di Hall of Justice!",
  str_n28_14_name_desc = "Pengadilan berada di bawah kendali mutlak Schwab! Tidak ada lagi kesempatan bagi keadilan untuk menang di sini. Kita harus mencari jalan keluar dulu, baru memikirkan cara lain!",
  str_n28_15_name_desc = "/",
  str_n28_1_name_desc_long = "Setelah festival Mooncrown Day berakhir, pesona asmara yang tersisa masih melayang di jalanan Lumopolis. Sepasang kekasih datang ke Hall of Justice dan membuat keributan. Kasus tersebut bahkan menarik perhatian Schwartz, yang kebetulan hadir untuk pemeriksaan. Menghadapi perubahan struktural yang akan datang ke Hall of Justice, beberapa hakim muda menunjukkan reaksi yang berbeda—Leyn terus bekerja tanpa sadar, Matthieu mengundang Anda dan Carleen untuk berbagi dalam kejadian yang menarik, dan Tina, yang selalu ceria, sepertinya memiliki kekhawatirannya sendiri.",
  str_n28_2_name_desc_long = "Kasus pertama Divisi Percintaan yang tak seorang pun mau tangani ada di tanganmu. Sebuah patung telah dipenggal dan penggugat bersikeras bahwa patung tak bernyawa itu adalah kekasihnya. Anda pergi ke tempat Hall of Justice menyimpan pameran kasus dan memeriksa patung untuk mencari petunjuk. Di luar jendela, \"bulan\" muncul dengan tenang.",
  str_n28_3_name_desc_long = "Tanpa petunjuk yang jelas untuk ditindaklanjuti, Tina mengundang Anda untuk mengunjungi rumahnya. Ternyata dia telah diganggu oleh sesuatu selama beberapa waktu dan berharap Anda dapat membantu rencananya untuk bertemu dengannya menjadi kenyataan. Anda langsung mengerti dari kata-kata Tina bahwa dia diam-diam jatuh cinta dengan bos baru Anda, Schwab.",
  str_n28_4_name_desc_long = "Anda memutuskan untuk pergi ke Moonlight Salon untuk mencoba keberuntungan Anda dan melihat apakah Anda dapat menemukan objek kasih sayang Tina. Tina juga membawa hadiah yang ingin dia berikan. Di salon, Anda menari, mengobrol, dan menikmati lagu-lagu meriah, tetapi penjaga kota tiba-tiba menghancurkan momen bahagia ini. Para penjaga sangat ingin menekan pertemuan pribadi ini, dan di tengah kekacauan, patung lain rusak, dan hadiah Tina hilang.",
  str_n28_5_name_desc_long = "Anda segera menuju ke Hall of Justice untuk melaporkan masalah tersebut, tetapi bertemu dengan sepasang kekasih lain yang bertekad untuk memasuki pertarungan hukum yang panas. Keduanya ternyata hadir di salon... Ternyata hadiah Tina yang hilang menyebabkan kesalahpahaman di antara mereka, dan meskipun Tina bergegas untuk menjelaskan situasinya, masalahnya berubah secara tak terduga ...",
  str_n28_6_name_desc_long = "Karena kesaksian Tina di pengadilan, Schwab akhirnya dipermalukan di depan semua orang. Setelah meninggalkan Hall of Justice, Anda menyadari bahwa Anda terlalu cepat menebak siapa yang disukai Tina, berdasarkan penjelasannya. Hadiah itu tidak pernah dimaksudkan untuk Schwab, tetapi sebenarnya dimaksudkan untuk Eclipsite kecil yang tampaknya muncul di mana-mana — Toto.",
  str_n28_7_name_desc_long = "Sebelum Anda bersiap untuk pergi, Loewe tiba-tiba membawa wawasan baru Carleen berupa informasi baru. Tampaknya setiap diadakan Moonlight Salon, kerusuhan pecah, dan kepala patung menghilang secara misterius. Sehubungan dengan terobosan ini, penyelenggara Moonlight Salon tampak sangat mencurigakan di mata Anda, tetapi ketika Anda bertemu dengan penyelenggara lagi, kecurigaan Anda langsung hilang.",
  str_n28_8_name_desc_long = "Byron, penggugat dalam kasus patung yang dipenggal, datang ke Hall of Justice untuk mengajukan pengaduan dan meminta untuk melihat hasil investigasi secepatnya. Karena kehabisan petunjuk, para juri mengganti kepala patung yang terpenggal itu karena putus asa. Tentu saja, Byron tidak terhibur dengan sikap ceroboh seperti itu, tetapi dia tidak punya waktu untuk tetap marah—\"istri patung\" kesayangannya sedang dalam bahaya. Para juri segera bergegas ke Stairway to the Skies, tempat parade akan diadakan.",
  str_n28_9_name_desc_long = "Patung yang membutuhkan perlindungan ada di puncak tangga, ke arah prosesi yang maju. Untuk menyelamatkan patung agar tidak hancur dalam kekacauan, para juri mencoba menghentikan pawai melalui cara yang tidak biasa. Saat Anda akan berhasil, Eclipsites mulai mengamuk di bagian belakang pawai, dan kerumunan melarikan diri menuju tangga.",
  str_n28_10_name_desc_long = "Anda mencoba untuk menjaga keamanan patung itu. Eclipsites menutup dari belakang kerumunan, dan panik mengelilingi. Dalam kekacauan pertempuran, tangan bayangan menjangkau dari kegelapan dan mematahkan kepala patung, tapi setidaknya Leyn berhasil menarik sarung tangan dari tangan pelakunya yang tidak dikenal. Byron yang patah hati kembali ke Hall of Justice, sementara Schwab tampaknya yakin bahwa dia telah menyelesaikan kasusnya, memerintahkan penangkapan Tina.",
  str_n28_11_name_desc_long = "Sarung tangan diperoleh oleh Leyn menjadi bukti kunci yang menunjukkan kesalahan Tina, dan Schwab menangkapnya. Anda sangat percaya itu Tina tidak bersalah dan tidak bisa mengabaikan perilaku aneh Schwab, seolah-olah dia menjebaknya. Mungkin jika kau bisa mengetahui motifnya, kau bisa membebaskannya Tina. Leyn memutuskan untuk mengambil risiko dan menyelinap ke rumah Schwab untuk melihat-lihat.",
  str_n28_12_name_desc_long = "Anda menyelinap ke rumah Schwab untuk mengamatinya. Meskipun perilaku Schwab agak aneh, tidak ada yang mencurigakan tentang dirinya. Anda membuka jalan ke ruang bawah tanah Schwab secara kebetulan, dan segerombolan Eclipsites muncul darinya. Anda melarikan diri dari rumah Schwab dengan panik — waktu hampir habis, karena hari persidangan semakin dekat.",
  str_n28_13_name_desc_long = "Uji coba \"Pemenggalan Patung Serial\" akhirnya dimulai. Leyn Dan Matthieu bersikeras bahwa Tina tidak bersalah, dan setelah pertahanan sengit, Leyn menerkam kontradiksi antara sarung tangan dan tangan Tina, berhasil membersihkan namanya. Namun, masalah ini masih jauh dari selesai. Leyn mengundang seorang saksi khusus untuk bersaksi. Toto telah datang ke kursi saksi, siap membuktikan bahwa pelaku sebenarnya adalah Schwab.",
  str_n28_14_name_desc_long = "Toto dan Leyn merencanakan strategi cerdik sebelumnya, di mana Toto berpura-pura menjadi pelaku yang bertanggung jawab atas perusakan patung, berhasil mengungkap plot Schwab. Dalam keputusasaannya, Schwab mengungkapkan kartu trufnya — dia telah mengganti anggota juri dengan Eclipsites! Putusannya tidak ada hubungannya dengan kebenaran. Anda melarikan diri dari Hall of Justice, tetapi dihadapkan oleh Schwab yang gila di gerbang. Pada akhirnya, Anda berhasil menaklukkannya. Kasus ini berakhir dengan meledaknya balon bulan—sepertinya gelombang asmara yang memenuhi udara akan memudar seiring dengan itu.",
  str_n28_15_name_desc_long = "Irridon mengadili kasus itu lagi dan menghukum pihak yang bersalah. Lelucon ini tidak berbahaya, jadi Schwab tidak akan dipenjara. Meski baginya, hukuman yang diterimanya mungkin lebih tak tertahankan daripada hukuman penjara. Anda dan para hakim juga menerima hukuman untuk perilaku tidak ortodoks Anda. Setelah menerima hadiah dari Tina, Toto siap memulai perjalanan baru; kepergiannya membuat Anda menantikan pertemuan berikutnya. Saat himne melayang di udara, Lumopolis kembali seperti semula.",
  str_n28_h1_name = "H1 - Serangan",
  str_n28_h2_name = "H2 - Din Mematikan",
  str_n28_h3_name = "H3 - Selesaikan",
  str_n28_h4_name = "H4 - Pengejaran",
  str_n28_h5_name = "H5 - pantang menyerah",
  str_n28_h6_name = "H6 - Kavaleri",
  str_n28_h7_name = "EX1 - Berjuang untuk Bertahan Hidup",
  str_n28_h8_name = "EX2 - Petir yang Membakar",
  str_n28_h9_name = "EX3 - Bayangan Berbilah",
  str_n28_h10_name = "EX4 - Kawanan",
  str_n28_h11_name = "EX5 - Kemarahan Darah",
  str_n28_h12_name = "EX 6 - Serangan Tengah",
  str_n28_h1_name_desc = "Musuh sulit ditangkap dan bergerak cepat, tetapi hal yang paling menakutkan adalah mereka bersedia mengorbankan hidup mereka untuk mengalahkan Anda.",
  str_n28_h2_name_desc = "Gemuruh guntur memenuhi udara. Saat mereka jatuh, mungkin Anda bisa menggunakan ledakan kuat mereka untuk menyerang musuh.",
  str_n28_h3_name_desc = "Meskipun musuh sangat banyak, dengan bantuan sekutu Anda, Anda mungkin bisa membalikkan keadaan.",
  str_n28_h4_name_desc = "Medannya rumit dan musuhmu banyak — bertahan hidup saja sudah merupakan keajaiban. Hati-hati terhadap musuh yang mengejar Anda!",
  str_n28_h5_name_desc = "Dikepung oleh musuh yang tak terhitung jumlahnya, bagaimana Anda bisa mengukir jalan berdarah menuju keselamatan? Terlebih lagi, begitu musuh ini mati, mereka menjadi semakin kuat ...",
  str_n28_h6_name_desc = "Mereka tampak seperti Ksatria Lumo, tetapi di balik topeng batu mereka terdapat Eclipsites yang ganas. Anda tidak boleh jatuh!",
  str_n28_h7_name_desc = "Pengejar Anda semakin dekat... Bagaimana sekutu Anda bisa bertahan?",
  str_n28_h8_name_desc = "Api dan gema ledakan mengelilingi... Musuh tampaknya tak terkalahkan, tetapi waktu akan menjadi kunci kemenangan Anda.",
  str_n28_h9_name_desc = "Bayangan mengintai di setiap sudut, dan bilah tajam mencari daging Anda di setiap belokan. Pertempuran yang sulit ada di depan Anda.",
  str_n28_h10_name_desc = "Genangan musuh yang tak ada habisnya membentuk kawanan yang mendidih, membanjiri dari sarang di area tengah ...",
  str_n28_h11_name_desc = "Bilah musuh setajam angin yang menggigit, dan serangan mereka lebih mematikan daripada badai yang mengamuk. Yang lebih menakutkan dari ini adalah kenyataan bahwa begitu mereka dimabukkan oleh bau darah, mereka menjadi lebih kuat...",
  str_n28_h12_name_desc = "Meskipun Anda tidak sepenuhnya yakin, musuh yang berdiri di tengah medan perang mungkin menyimpan niat tersembunyi...",
  str_n28_main_btn_unlock_time = "Terbuka setelah {1}{2}{3}",
